impl Solution {
    pub fn max_in_table(n: u32) -> u32 {
        let n_int = n as i32;
        table_value(n_int, (n - 1) as i32, (n - 1) as i32) as u32
    }

    fn table_value(n: i32, i: i32, j: i32) -> i32 {
        if i < 0 || j < 0 || i >= n || j >= n {
            0
        } else if i == 0 || j == 0 {
            1
        } else {
            table_value(n, i - 1, j) + table_value(n, i, j - 1)
        }
    }
}

